import { closeSync, openSync, readSync } from 'node:fs';
import { dirname, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execa, execaSync, ExecaError } from 'execa';
import { Fixes } from './fixes.js';
import type { OxlintFormat, OxlintNodeOptions } from './options.js';
import { Plugins } from './plugins.js';
import { resolveBin, resolveTsgolintBin } from './resolve-bin.js';
import { Rules } from './rules.js';

const moduleDir = dirname(fileURLToPath(import.meta.url));

const JS_EXTENSIONS = new Set(['.js', '.mjs', '.cjs']);

/**
 * Whether the bin is a Node.js script (e.g. `oxlint/bin/oxlint`, which has no
 * extension and a `#!/usr/bin/env node` shebang) rather than a native executable.
 */
function isNodeScript(binPath: string): boolean {
  if (JS_EXTENSIONS.has(extname(binPath).toLowerCase())) return true;
  let fd: number | undefined;
  try {
    fd = openSync(binPath, 'r');
    const buffer = Buffer.alloc(128);
    const bytesRead = readSync(fd, buffer, 0, buffer.length, 0);
    const firstLine = buffer.toString('utf8', 0, bytesRead).split('\n')[0];
    return firstLine.startsWith('#!') && firstLine.includes('node');
  } catch {
    return false;
  } finally {
    if (fd !== undefined) closeSync(fd);
  }
}

type OxlintRuntimeOptions = Omit<
  OxlintNodeOptions,
  | 'pluginsFlags'
  | 'rulesFlags'
  | 'fixesFlags'
  | 'formats'
  | 'configPath'
  | 'tsconfigPath'
  | 'binPath'
  | 'tsgolintBinPath'
>;

export type OxlintJsonLabel = {
  label?: string;
  span: {
    offset: number;
    length: number;
    line: number;
    column: number;
  };
};

export type OxlintJsonDiagnostic = {
  message: string;
  code: string;
  severity: 'error' | 'warning';
  url?: string;
  help?: string;
  filename: string;
  labels: OxlintJsonLabel[];
};

export type OxlintJsonResult = {
  diagnostics: OxlintJsonDiagnostic[];
  number_of_files: number;
  number_of_rules: number;
  threads_count: number;
  start_time: number;
};

export type OxlintMultiFormatResult = {
  [Format in OxlintFormat]?: Format extends 'json'
    ? OxlintJsonResult
    : string;
};

export class OxlintNode {
  constructor(
    public binPath: string,
    public plugins: Plugins,
    public rules: Rules,
    public fixes: Fixes,
    public formats: OxlintFormat[] = ['default'],
    public configPath?: string,
    public tsconfigPath?: string,
    private options: OxlintRuntimeOptions = {},
    private tsgolintBinPath?: string
  ) {}

  version(): string {
    const [command, commandArgs] = this.getCommand(['--version']);
    return execaSync(command, commandArgs).stdout.trim();
  }

  /**
   * Windows cannot execute a shebang script directly (it fails with "is not
   * recognized as an internal or external command"), so Node.js scripts are run
   * through the current Node.js executable on every platform.
   */
  private getCommand(args: string[]): [string, string[]] {
    if (isNodeScript(this.binPath)) {
      return [process.execPath, [this.binPath, ...args]];
    }
    return [this.binPath, args];
  }

  private getConfigCliArg(): string {
    return this.configPath ? `--config=${this.configPath}` : '';
  }

  private getTsConfigCliArg(): string {
    return this.tsconfigPath ? `--tsconfig=${this.tsconfigPath}` : '';
  }

  private getFormatCliArg(format: OxlintFormat): string {
    return `--format=${format}`;
  }

  private getExtraCliArgs(): string[] {
    const args: string[] = [];
    const options = this.options;
    if (options.ignorePath) args.push(`--ignore-path=${options.ignorePath}`);
    options.ignorePatterns?.forEach((pattern) =>
      args.push(`--ignore-pattern=${pattern}`)
    );
    if (options.noIgnore) args.push('--no-ignore');
    if (options.quiet) args.push('--quiet');
    if (options.denyWarnings) args.push('--deny-warnings');
    if (options.maxWarnings !== undefined) {
      args.push(`--max-warnings=${options.maxWarnings}`);
    }
    if (options.silent) args.push('--silent');
    if (options.noErrorOnUnmatchedPattern) {
      args.push('--no-error-on-unmatched-pattern');
    }
    if (options.threads !== undefined) {
      args.push(`--threads=${options.threads}`);
    }
    if (options.printConfig) args.push('--print-config');
    if (options.reportUnusedDisableDirectivesSeverity) {
      args.push(
        `--report-unused-disable-directives-severity=${options.reportUnusedDisableDirectivesSeverity}`
      );
    } else if (options.reportUnusedDisableDirectives) {
      args.push('--report-unused-disable-directives');
    }
    if (options.disableNestedConfig) args.push('--disable-nested-config');
    if (options.typeAware) args.push('--type-aware');
    if (options.typeCheck) args.push('--type-check');
    return args;
  }

  async run(paths: string[] = []): Promise<OxlintMultiFormatResult> {
    const result: OxlintMultiFormatResult = {};

    // Run formats sequentially. Multiple format processes may otherwise race while
    // applying fixes to the same files.
    for (let formatIndex = 0; formatIndex < this.formats.length; formatIndex += 1) {
      const format = this.formats[formatIndex];
      const batches = this.batchPaths(format, paths);
      const batchResults: Array<string | OxlintJsonResult> = [];
      for (let batchIndex = 0; batchIndex < batches.length; batchIndex += 1) {
        // eslint-disable-next-line no-await-in-loop
        batchResults.push(await this.runFormatBatch(format, batches[batchIndex]));
      }
      (result as Record<OxlintFormat, string | OxlintJsonResult>)[format] =
        this.mergeFormatResults(format, batchResults);
    }

    return result;
  }

  private async runFormatBatch(
    format: OxlintFormat,
    paths: string[]
  ): Promise<string | OxlintJsonResult> {
    const args = this.toCliArgs(format, paths);
    const env: Record<string, string> = {
      FORCE_COLOR: format === 'json' ? '0' : '1',
    };
    if (this.tsgolintBinPath) {
      env.OXLINT_TSGOLINT_PATH = this.tsgolintBinPath;
    }

    let stdout: string;
    let stderr = '';
    let exitCode: number | undefined = 0;
    try {
      const [command, commandArgs] = this.getCommand(args);
      ({ stdout, stderr } = await execa(command, commandArgs, { env }));
    } catch (error) {
      // Exit code 1 represents lint findings (including denied warnings), so its
      // output is a valid result. Configuration and process failures are re-thrown.
      if (
        !(error instanceof ExecaError) ||
        error.exitCode !== 1 ||
        typeof error.stdout !== 'string'
      ) {
        throw error;
      }
      stdout = error.stdout;
      stderr = typeof error.stderr === 'string' ? error.stderr : '';
      exitCode = error.exitCode;
    }

    if (format !== 'json') return stdout;

    if (
      stdout.trim() === '' &&
      exitCode === 0 &&
      this.options.noErrorOnUnmatchedPattern
    ) {
      return {
        diagnostics: [],
        number_of_files: 0,
        number_of_rules: 0,
        threads_count: 0,
        start_time: 0,
      };
    }

    try {
      return JSON.parse(stdout) as OxlintJsonResult;
    } catch {
      // When the Oxlint process itself fails (e.g. its native binding cannot be
      // loaded), it exits with code 1 and the actual error is only on stderr.
      const stderrMsg = stderr.trim() ? `\nstderr:\n${stderr}` : '';
      throw new Error(
        `oxlint returned non-JSON output (exit code ${exitCode}):\n${stdout}${stderrMsg}`
      );
    }
  }

  /**
   * Keep each command below the platform command-line limit. Batches and formats
   * are intentionally run sequentially to avoid oversubscribing CPU and racing fixes.
   */
  private batchPaths(format: OxlintFormat, paths: string[]): string[][] {
    if (paths.length <= 1) return [paths];
    const maxCommandLength = process.platform === 'win32' ? 30000 : 130000;
    const fixedArgs = this.toCliArgs(format, []);
    const [command, commandArgs] = this.getCommand(fixedArgs);
    const overhead = command.length + commandArgs.join(' ').length + 1;
    const budget = Math.max(2000, maxCommandLength - overhead);

    const batches: string[][] = [];
    let current: string[] = [];
    let currentLength = 0;
    paths.forEach((filePath) => {
      const pathLength = filePath.length + 1;
      if (current.length > 0 && currentLength + pathLength > budget) {
        batches.push(current);
        current = [];
        currentLength = 0;
      }
      current.push(filePath);
      currentLength += pathLength;
    });
    if (current.length > 0) batches.push(current);
    return batches;
  }

  private mergeFormatResults(
    format: OxlintFormat,
    results: Array<string | OxlintJsonResult>
  ): string | OxlintJsonResult {
    if (results.length === 1) return results[0];
    if (format !== 'json') return (results as string[]).join('\n');

    const jsonResults = results as OxlintJsonResult[];
    const first = jsonResults[0];
    return jsonResults.slice(1).reduce<OxlintJsonResult>(
      (merged, batch) => ({
        ...merged,
        diagnostics: [...merged.diagnostics, ...batch.diagnostics],
        number_of_files: merged.number_of_files + batch.number_of_files,
        start_time: Math.min(merged.start_time, batch.start_time),
      }),
      { ...first, diagnostics: [...first.diagnostics] }
    );
  }

  toCliArgs(format: OxlintFormat, paths: string[] = []): string[] {
    return [
      ...paths,
      ...this.plugins.toCliArgs(),
      ...this.rules.toCliArgs(),
      ...this.fixes.toCliArgs(),
      ...this.getExtraCliArgs(),
      this.getConfigCliArg(),
      this.getTsConfigCliArg(),
      this.getFormatCliArg(format),
    ].filter(Boolean);
  }

  static create(options: OxlintNodeOptions = {}): OxlintNode {
    const excludedRuntimeKeys = new Set<keyof OxlintNodeOptions>([
      'pluginsFlags',
      'rulesFlags',
      'fixesFlags',
      'formats',
      'configPath',
      'tsconfigPath',
      'binPath',
      'tsgolintBinPath',
    ]);
    const runtimeOptions = Object.fromEntries(
      Object.entries(options).filter(
        ([key]) => !excludedRuntimeKeys.has(key as keyof OxlintNodeOptions)
      )
    ) as OxlintRuntimeOptions;
    const binPath =
      options.binPath ||
      resolveBin('oxlint', { executable: 'oxlint', paths: [moduleDir] });

    let tsgolintBinPath = options.tsgolintBinPath;
    if (!tsgolintBinPath && (runtimeOptions.typeAware || runtimeOptions.typeCheck)) {
      try {
        tsgolintBinPath = resolveTsgolintBin([moduleDir]);
      } catch {
        try {
          tsgolintBinPath = resolveBin('oxlint-tsgolint', {
            executable: 'tsgolint',
            paths: [moduleDir],
          });
        } catch {
          // Oxlint will provide the actionable error if type-aware linting runs
          // without a compatible tsgolint binary.
        }
      }
    }

    return new OxlintNode(
      binPath,
      Plugins.from(options.pluginsFlags || {}),
      Rules.from(options.rulesFlags || []),
      Fixes.from(options.fixesFlags || {}),
      options.formats,
      options.configPath,
      options.tsconfigPath,
      runtimeOptions,
      tsgolintBinPath
    );
  }
}
